            **RUNS[source], 'recipe':'zs','init_from':source,'format':fmt,
            'bounded_reasoning':fmt=='cot','native_schedule':'full_reasoning',
            'eval_schedule':'full_reasoning','validation_protocol':'fixed_single_sequence',
